@pytest.mark.parametrize("close", ["cancel", "escape", "backdrop", "backdrop-over-by-item"]) def test_R30_leaving_the_dialog_without_starting_over(open_app, close): # [v1.1.0] qa.md over K2. The backdrop point is (20, 20) and the control under the backdrop is the By item half of the # Split switch. Each close waits for the dialog's close event before focus is read (`closing`, spec R59 (2), F-A3-1). page = open_app(seed=seeds.S2).page by_item = centre_of(page.locator("label[for=modeItem]")) open_dialog(page) box = page.locator("dialog#newDlg").bounding_box() assert outside(box, (20, 20)) and outside(box, by_item), "a backdrop point lies on the dialog" closing(page, m1_closer(page, close, by_item)) assert dialog_is_open(page) is False > assert focused(page) == "New bill" and stored_text(page) == seeds.S2 E AssertionError: assert ('Splits' == 'New bill' E E - New bill E + Splits)
